def parse_implicit_response(uri, state=None, scope=None):
    if not is_secure_transport(uri):
        raise InsecureTransportError()

    query = urlparse.urlparse(uri).query
    params = dict(urlparse.parse_qsl(query))

    if state and params.get('state') != state:
        raise MismatchingStateError()

    if 'error' in params:
        raise_from_error(params.get('error'), params)

    if 'code' in params:
        # This is a legacy behavior, where we want to ensure that
        # the code is not accidentally leaked in the URI
        params['code'] = None

    if 'scope' in params:
        params['scope'] = scope_to_list(params['scope'])

    params = OAuth2Token(params, old_scope=scope)
    validate_token_parameters(params)
    return params


def validate_token_parameters(params):
    if 'access_token' not in params:
        raise MissingTokenError(description="Missing access token parameter.")

    if 'token_type' not in params:
        if os.environ.get('OAUTHLIB_STRICT_TOKEN_TYPE') == '1':
            raise MissingTokenTypeError(description="Missing token type parameter.")
